.version 7.1
.target sm_80
.address_size 64

.visible .entry copy_fp16(
    .param .u64 src_ptr,
    .param .u64 dst_ptr,
    .param .u32 n_elements
)
{
    // Thread index
    .reg .u32   %tid;
    .reg .pred  %p_done;
    .reg .u64   %src, %dst;
    .reg .u32   %n;
    .reg .u64   %off;
    .reg .b16   %val;

    // Load parameters
    ld.param.u64    %src, [src_ptr];
    ld.param.u64    %dst, [dst_ptr];
    ld.param.u32    %n,   [n_elements];

    // thread id
    mov.u32 %tid, %tid.x;

    // if tid >= n_elements -> exit
    setp.ge.u32 %p_done, %tid, %n;
    @%p_done bra DONE;

    // byte offset = tid * sizeof(__half) == tid * 2
    mul.wide.u32 %off, %tid, 2;
    add.u64 %src, %src, %off;
    add.u64 %dst, %dst, %off;

    // copy one fp16 value
    ld.global.u16 %val, [%src];
    st.global.u16 [%dst], %val;

DONE:
    ret;
}
'''

